class Solution {
public:
 vector<int> minReverseOperations(int n,int p,vector<int>& banned,int k) {
  vector<int> dist(n,-1);
  set<int> unused[2];
  vector<char> blocked(n,false);
  for(int b:banned)blocked[b]=true;
  for(int i=0;i<n;++i)if(i!=p&&!blocked[i])unused[i&1].insert(i);
  queue<int> q;q.push(p);dist[p]=0;
  while(!q.empty()){
   int i=q.front();q.pop();
   int lo=2*max(0,i-k+1)+k-1-i;
   int hi=2*min(i,n-k)+k-1-i;
   auto &s=unused[lo&1];
   auto it=s.lower_bound(lo);
   while(it!=s.end()&&*it<=hi){int j=*it;it=s.erase(it);dist[j]=dist[i]+1;q.push(j);}
  }
  return dist;
 }
};
